import json, os
_vars = json.loads(os.environ.get('RPA_VARIABLES_JSON', '{}'))
raw = _vars.get('orders_response', '')
try:
    payload = json.loads(raw) if isinstance(raw, str) else raw
except Exception as exc:
    raise SystemExit(f'接口返回不是有效 JSON: {exc}')

orders = payload
if isinstance(payload, dict):
    for key in ('orders', 'data', 'items', 'list', 'records'):
        if isinstance(payload.get(key), list):
            orders = payload[key]
            break

if not isinstance(orders, list):
    raise SystemExit('未找到订单列表：期望返回数组，或包含 orders/data/items/list/records 数组字段')

output_dir = _vars.get('output_dir', '.')
os.makedirs(output_dir, exist_ok=True)
path = os.path.join(output_dir, f"orders_{_vars.get('run_timestamp', 'run')}.jsonl")
with open(path, 'w', encoding='utf-8') as f:
    for order in orders:
        f.write(json.dumps(order, ensure_ascii=False) + '\n')
print(path)
